CREATE OR REPLACE FUNCTION public.issue_company_setup(_details jsonb, _create_now boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'extensions' AS $function$ DECLARE token text; company uuid; invitation uuid; email_value text:=lower(trim(_details->>'email')); BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform administrator required' USING ERRCODE='42501'; END IF; PERFORM public.validate_company_setup(_details); IF email_value IS NULL OR email_value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(email_value)>255 THEN RAISE EXCEPTION 'Customer email required'; END IF; IF EXISTS(SELECT 1 FROM public.company_setup_invitations WHERE created_by=auth.uid() AND created_at>now()-interval '1 minute' GROUP BY created_by HAVING count(*)>=10) THEN RAISE EXCEPTION 'Please wait before creating more invitations'; END IF; token:=encode(gen_random_bytes(32),'hex'); IF _create_now THEN INSERT INTO public.organizations(name,onboarding_status) VALUES(trim(_details->>'company_name'),'pending') RETURNING id INTO company; INSERT INTO public.company_admin_access(user_id,org_id,granted_by) SELECT p.user_id,company,auth.uid() FROM public.profiles p WHERE lower(p.email)=email_value AND p.org_id IS NOT NULL ON CONFLICT DO NOTHING; END IF; INSERT INTO public.company_setup_invitations(org_id,email,company_name,token_hash,defaults,created_by) VALUES(company,email_value,trim(_details->>'company_name'),encode(digest(token,'sha256'),'hex'),_details,auth.uid()) RETURNING id INTO invitation; RETURN jsonb_build_object('id',invitation,'token',token,'org_id',company,'expires_at',now()+interval '7 days'); END $function$;

DO $m$ DECLARE def text; BEGIN
SELECT pg_get_functiondef('public.complete_company_setup(uuid,text,jsonb)'::regprocedure) INTO def;
def := replace(def, $r$IF NOT FOUND OR existing IS NOT NULL THEN RAISE EXCEPTION 'This account is already assigned or its profile is unavailable'; END IF;$r$, $r$IF NOT FOUND THEN RAISE EXCEPTION 'This account profile is unavailable'; END IF;$r$);
def := replace(def, $r$UPDATE public.profiles SET org_id=company WHERE user_id=_user AND org_id IS NULL;$r$, $r$IF existing IS NOT NULL AND existing<>company THEN INSERT INTO public.company_admin_access(user_id,org_id,granted_by) VALUES(_user,company,_user) ON CONFLICT DO NOTHING; END IF; UPDATE public.profiles SET org_id=company WHERE user_id=_user AND org_id IS NULL;$r$);
IF position('company_admin_access' in def)=0 OR position('already assigned' in def)>0 THEN RAISE EXCEPTION 'complete_company_setup patch failed'; END IF;
EXECUTE def;
END $m$;